// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb7", fn: function () { return String(dma_ListApplComDetail.get("dpFromEmpCnt")) + " 명"; } },
        { childId: "__rb13", fn: function () { return String(dma_ListApplComDetail.get("dpFromAcntclsMmdd")) + " 월"; } },
        { childId: "__rb21", fn: function () { return String(dma_ListApplComDetail.get("dpFromLgshrhdRto")) + " %"; } },
        { childId: "__rb24", fn: function () { return String(dma_ListApplComDetail.get("dpFromListShrs")) + " 주"; } },
        { childId: "__rb25", fn: function () { return String(dma_ListApplComDetail.get("pubofrSchdlShrs")) + " 주"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

